<script setup>
import { computed, reactive, ref, watch } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
const props=defineProps({modelValue:Boolean,license:Object,customer:Object,mode:{type:String,default:'edit'}})
const emit=defineEmits(['update:modelValue','saved'])
const open=computed({get:()=>props.modelValue,set:value=>emit('update:modelValue',value)})
const $q=useQuasar(),busy=ref(false),form=reactive({permanent:true,durationDays:30,kind:'days',date:''})
const title=computed(()=>props.mode==='grant'?'Liberar licença para o cliente':props.mode==='renew'?'Renovar validade da licença':'Editar validade da licença')
watch(()=>props.modelValue,value=>{if(!value)return;form.permanent=props.license?.permanent!==false&&!props.license?.expiresAt;form.durationDays=props.license?.durationDays||30;form.kind='days';const expiry=props.license?.expiresAt?new Date(props.license.expiresAt):new Date(Date.now()+30*86400000);form.date=new Date(expiry.getTime()-expiry.getTimezoneOffset()*60000).toISOString().slice(0,16)})
async function save(){
 let body={permanent:form.permanent}
 if(!form.permanent){if(form.kind==='date'){const value=new Date(form.date);if(!Number.isFinite(value.getTime())||value<=new Date())return $q.notify({type:'warning',message:'Escolha uma data futura.'});body.expiresAt=value.toISOString()}else{const days=Number(form.durationDays);if(!Number.isInteger(days)||days<1||days>36500)return $q.notify({type:'warning',message:'Informe um prazo de 1 a 36.500 dias.'});body.durationDays=days}}
 busy.value=true
 try{const config={headers:{Authorization:'Bearer '+localStorage.getItem('aito_admin_token')}};let result;if(props.mode==='grant')result=await api.post(`/admin/products/aitonotify/customers/${props.customer._id||props.customer.id}/license`,body,config);else if(props.mode==='renew')result=await api.post(`/admin/botbuilder/licenses/${props.license._id||props.license.id}/renew`,body,config);else result=await api.patch(`/admin/botbuilder/licenses/${props.license._id||props.license.id}`,body,config);emit('saved',result.data.data);open.value=false;$q.notify({type:'positive',message:'Licença e validade atualizadas.'})}catch(error){$q.notify({type:'negative',message:error.response?.data?.message||'Não foi possível atualizar a validade.'})}finally{busy.value=false}
}
</script>
<template><q-dialog v-model="open" persistent><q-card class="license-term-card"><q-card-section class="license-term-head"><div><span>ADMINISTRAÇÃO DE LICENÇAS</span><h3>{{title}}</h3><p>{{customer?.name||license?.ownerName||license?.ownerEmail||'Kit AitoNotify + WhatsApp BotBuilder'}}</p></div><q-btn flat round dense icon="mdi-close" aria-label="Fechar validade" :disable="busy" @click="open=false"/></q-card-section><q-form @submit.prevent="save"><q-card-section class="license-term-fields"><q-toggle v-model="form.permanent" color="teal" label="Licença permanente, sem data de expiração"/><template v-if="!form.permanent"><q-btn-toggle v-model="form.kind" no-caps unelevated toggle-color="teal-8" :options="[{label:'Prazo em dias',value:'days'},{label:'Data exata',value:'date'}]"/><q-input v-if="form.kind==='days'" v-model="form.durationDays" outlined type="number" min="1" max="36500" label="Duração em dias" hint="Exemplos: 1 dia para teste, 30 dias para um período mensal."/><q-input v-else v-model="form.date" outlined type="datetime-local" label="Válida até" stack-label/></template><q-banner rounded class="license-term-note">{{mode==='renew'?'O novo prazo começa agora e a licença será reativada. O token e a instalação são preservados. Confira o novo vencimento após salvar.':mode==='grant'?'Este é um acesso liberado pelo administrador. A operação não registra um pagamento fictício.':'Editar o prazo preserva o token e não reativa uma licença suspensa automaticamente.'}}</q-banner></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancelar" :disable="busy" @click="open=false"/><q-btn unelevated no-caps color="teal-8" type="submit" :label="mode==='renew'?'Renovar licença':mode==='grant'?'Liberar licença':'Salvar validade'" :loading="busy"/></q-card-actions></q-form></q-card></q-dialog></template>
<style scoped>.license-term-card{width:min(560px,calc(100vw - 26px));border-radius:22px;background:linear-gradient(145deg,#f7fffb,#e6f6ee);color:#143d30;border:1px solid #9fd8c1}.license-term-head{display:flex;gap:12px;align-items:flex-start;border-bottom:1px solid #c4e1d3}.license-term-head>div{flex:1}.license-term-head span{font-size:9px;letter-spacing:.1em;color:#3e846b;font-weight:800}.license-term-head h3{font-size:23px;line-height:1.3;margin:10px 0}.license-term-head p{font-size:12px;line-height:1.6;color:#658678;margin:0;overflow-wrap:anywhere}.license-term-fields{display:grid;gap:20px}.license-term-note{background:#d7eee2;color:#496e5d;font-size:11px;line-height:1.8}.license-term-card :deep(.q-card__actions){border-top:1px solid #c4e1d3;padding:16px}@media(max-width:450px){.license-term-head h3{font-size:20px}.license-term-card :deep(.q-card__actions){display:grid;grid-template-columns:1fr 1fr}}</style>
